            counts = {}
            for dread in pcol.pileups:
                if dread.is_del or dread.is_refskip:
                    b = 'DEL'
                else:
                    b = dread.alignment.query_sequence[dread.query_position].upper()
                counts[b] = counts.get(b, 0) + 1
            total = sum(counts.values())
            ref_count = counts.get(ref_base, 0)
            non_ref = total - ref_count
            af = non_ref / total if total > 0 else 0
            if af >= 0.05 and total >= 20 and non_ref >= 3:
