import pysam
from collections import defaultdict

pairs = {
    'PT-0204': ('CG24-2309', 'CG24-1557'),
    'PT-0476': ('CG24-9370', 'CG24-4358'),
    'PT-0789': ('CG24-3081', 'CG24-6922')
}

targets = []
with open('/task/input/targets.bed') as f:
    for line in f:
        chrom, s, e = line.strip().split()[:3]
        targets.append((chrom, int(s), int(e)))

ref = pysam.FastaFile('/task/work/ref.fa')

for patient, (t_id, n_id) in pairs.items():
    tbam = pysam.AlignmentFile(f'/task/work/{t_id}.bam')
    nbam = pysam.AlignmentFile(f'/task/work/{n_id}.bam')

    # Let's inspect all non-reference events with >= 5 fragments in tumour
    # 1. SNVs
    snv_candidates = []
    for chrom, s, e in targets:
        for pcol in tbam.pileup(chrom, s, e, truncate=True, min_base_quality=20, min_mapping_quality=20):
            pos = pcol.pos # 0-based
            rbase = ref.fetch(chrom, pos, pos+1).upper()
            # per-fragment call
            t_frag = {}
            for read in pcol.pileups:
                if read.is_del or read.is_refskip:
                    continue
                b = read.alignment.query_sequence[read.query_position].upper()
                qn = read.alignment.query_name
                if qn not in t_frag:
                    t_frag[qn] = set()
                t_frag[qn].add(b)

            counts = defaultdict(int)
            for qn, bset in t_frag.items():
                if len(bset) == 1:
                    counts[list(bset)[0]] += 1

            t_total = sum(counts.values())
            for alt, cnt in counts.items():
                if alt != rbase:
                    af = cnt / t_total if t_total > 0 else 0
                    if af >= 0.045 and cnt >= 5:
                        # check normal
                        n_frag = {}
                        for npcol in nbam.pileup(chrom, pos, pos+1, truncate=True, min_base_quality=20, min_mapping_quality=20):
                            if npcol.pos == pos:
                                for read in npcol.pileups:
                                    if read.is_del or read.is_refskip:
                                        continue
                                    nb = read.alignment.query_sequence[read.query_position].upper()
                                    qn = read.alignment.query_name
                                    if qn not in n_frag:
                                        n_frag[qn] = set()
                                    n_frag[qn].add(nb)
                                break
                        n_counts = defaultdict(int)
                        for qn, bset in n_frag.items():
                            if len(bset) == 1:
                                n_counts[list(bset)[0]] += 1
                        n_total = sum(n_counts.values())
                        n_cnt = n_counts.get(alt, 0)
                        n_af = n_cnt / n_total if n_total > 0 else 0
                        snv_candidates.append({
                            'chrom': chrom,
                            'pos': pos + 1,
                            'ref': rbase,
                            'alt': alt,
                            't_cnt': cnt,
                            't_tot': t_total,
                            't_af': af,
                            'n_cnt': n_cnt,
                            'n_tot': n_total,
                            'n_af': n_af
                        })

    # 2. Indels
    # Scan reads for indels
    indel_candidates = []
    t_indels = defaultdict(set)
    for chrom, s, e in targets:
        for read in tbam.fetch(chrom, s, e):
            if read.is_secondary or read.is_supplementary or read.mapping_quality < 20:
                continue
            qn = read.query_name
            ref_p = read.reference_start
            q_p = 0
            for op, length in read.cigartuples:
                if op == 0: ref_p += length; q_p += length
                elif op == 1:
                    ins_seq = read.query_sequence[q_p:q_p+length]
                    t_indels[(chrom, ref_p, 'INS', ins_seq)].add(qn)
                    q_p += length
                elif op == 2:
                    del_seq = ref.fetch(chrom, ref_p, ref_p+length)
                    t_indels[(chrom, ref_p, 'DEL', length, del_seq)].add(qn)
                    ref_p += length
                elif op == 4: q_p += length

    for indel_key, frags in t_indels.items():
        if len(frags) >= 5:
            chrom, pos, itype = indel_key[0], indel_key[1], indel_key[2]
            cov_frags = set()
            for read in tbam.fetch(chrom, max(0, pos-1), pos+1):
                if read.reference_start <= pos and read.reference_end >= pos:
                    cov_frags.add(read.query_name)
            af = len(frags) / len(cov_frags) if cov_frags else 0
            if af >= 0.045:
                # check normal
                n_frags = set()
                n_cov_frags = set()
                for read in nbam.fetch(chrom, max(0, pos-1), pos+1):
                    if read.reference_start <= pos and read.reference_end >= pos:
                        n_cov_frags.add(read.query_name)
                    ref_p = read.reference_start
                    q_p = 0
                    for op, length in read.cigartuples:
                        if op == 0: ref_p += length; q_p += length
                        elif op == 1:
                            if itype == 'INS' and ref_p == pos and read.query_sequence[q_p:q_p+length] == indel_key[3]:
                                n_frags.add(read.query_name)
                            q_p += length
                        elif op == 2:
                            if itype == 'DEL' and ref_p == pos and length == indel_key[3]:
                                n_frags.add(read.query_name)
                            ref_p += length
                        elif op == 4: q_p += length
                n_af = len(n_frags) / len(n_cov_frags) if n_cov_frags else 0
                indel_candidates.append({
                    'chrom': chrom,
                    'pos': pos,
                    'key': indel_key,
                    't_cnt': len(frags),
                    't_tot': len(cov_frags),
                    't_af': af,
                    'n_cnt': len(n_frags),
                    'n_tot': len(n_cov_frags),
                    'n_af': n_af
                })

    print(f'=== {patient} ===')
    # somatic filter: n_af < 0.02 and n_cnt <= 1
    somatic_snvs = [x for x in snv_candidates if x['n_af'] < 0.02 and x['n_cnt'] <= 1]
    somatic_indels = [x for x in indel_candidates if x['n_af'] < 0.02 and x['n_cnt'] <= 1]
    print(f'Somatic SNVs (AF >= 4.5%): {len(somatic_snvs)}')
    for s in sorted(somatic_snvs, key=lambda x: x['pos']):
        print(f"  SNV: {s['chrom']}:{s['pos']} {s['ref']}->{s['alt']} AF={s['t_af']:.3f} (T={s['t_cnt']}/{s['t_tot']} N={s['n_cnt']}/{s['n_tot']})")
    print(f'Somatic Indels (AF >= 4.5%): {len(somatic_indels)}')
    for ind in sorted(somatic_indels, key=lambda x: x['pos']):
        print(f"  INDEL: {ind['key']} AF={ind['t_af']:.3f} (T={ind['t_cnt']}/{ind['t_tot']} N={ind['n_cnt']}/{ind['n_tot']})")
